using System.Text.Json;
using Crusaders.Mainframe.Api.Payments.PayFast;

namespace Crusaders.Mainframe.Tests;

/// <summary>
/// The PayFast signature against a corpus generated by an independent implementation.
///
/// <para>
/// The signature is the part of a payment integration most likely to be got subtly wrong,
/// and a mismatch produces no useful error — PayFast rejects the payment or the ITN with no
/// indication of which byte differed. So it is pinned the same way the device protocol is:
/// vectors produced by a third implementation, executed-count asserted, and neither side
/// able to drift without this going red.
/// </para>
///
/// <para>
/// <b>Scope, stated honestly:</b> this proves conformance to PayFast's documented algorithm.
/// It is not verified against their live sandbox — no sandbox credentials were available —
/// so the first live transaction remains a real milestone.
/// </para>
/// </summary>
public class PayFastSignatureTests
{
    private static readonly JsonElement Corpus = Load("cases.json");
    private static readonly JsonElement Manifest = Load("manifest.json");

    private static JsonElement Load(string file)
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null)
        {
            var candidate = Path.Combine(dir.FullName, "src", "contracts", "payfast", file);
            if (File.Exists(candidate)) return JsonDocument.Parse(File.ReadAllText(candidate)).RootElement;
            dir = dir.Parent;
        }

        throw new FileNotFoundException(
            $"src/contracts/payfast/{file} was not found above the test binary. A missing corpus " +
            "must fail loudly rather than skip — it is the only thing pinning this signature.");
    }

    private static int Declared(string section) =>
        Manifest.GetProperty("case_count").GetProperty(section).GetInt32();

    private static string Passphrase => Corpus.GetProperty("passphrase").GetString()!;

    private static List<KeyValuePair<string, string?>> FieldsOf(JsonElement c) =>
        c.GetProperty("fields").EnumerateArray()
            .Select(f => new KeyValuePair<string, string?>(
                f.GetProperty("key").GetString()!,
                f.GetProperty("value").ValueKind == JsonValueKind.Null ? null : f.GetProperty("value").GetString()))
            .ToList();

    private static string? PassphraseOf(JsonElement c) =>
        c.GetProperty("passphrase").ValueKind == JsonValueKind.Null ? null : c.GetProperty("passphrase").GetString();

    // ---- The encoder -------------------------------------------------------

    [Fact]
    public void Url_encoding_matches_php_on_every_vector()
    {
        var executed = 0;

        foreach (var c in Corpus.GetProperty("encode").EnumerateArray())
        {
            var raw = c.GetProperty("raw").GetString()!;
            var expected = c.GetProperty("encoded").GetString()!;

            Assert.Equal(expected, PayFastSignature.UrlEncode(raw));
            executed++;
        }

        Assert.Equal(Declared("encode"), executed);
    }

    /// <summary>
    /// The three specific places .NET's own escaping would have been wrong, asserted
    /// individually so a failure names the rule rather than a vector index.
    /// </summary>
    [Fact]
    public void The_three_divergences_from_dotnet_are_handled()
    {
        // 1. Space is '+', not %20.
        Assert.Equal("Court+1", PayFastSignature.UrlEncode("Court 1"));
        Assert.Equal("Court%201", Uri.EscapeDataString("Court 1"));

        // 2. '~' is escaped by PHP and left literal by .NET.
        Assert.Equal("a%7Eb", PayFastSignature.UrlEncode("a~b"));
        Assert.Equal("a~b", Uri.EscapeDataString("a~b"));

        // 3. Hex is uppercase.
        Assert.Equal("%40", PayFastSignature.UrlEncode("@"));
        Assert.DoesNotContain("%7e", PayFastSignature.UrlEncode("~"), StringComparison.Ordinal);
    }

    /// <summary>Multi-byte characters encode per UTF-8 byte, not per character.</summary>
    [Fact]
    public void Multi_byte_characters_encode_per_byte()
    {
        // é is U+00E9 → C3 A9 in UTF-8, so two groups, not one.
        Assert.Equal("caf%C3%A9", PayFastSignature.UrlEncode("café"));
    }

    // ---- Payment request ---------------------------------------------------

    [Fact]
    public void Payment_request_signatures_match_every_vector()
    {
        var executed = 0;

        foreach (var c in Corpus.GetProperty("payment_request").EnumerateArray())
        {
            var fields = FieldsOf(c);
            var passphrase = PassphraseOf(c);
            var id = c.GetProperty("id").GetString();

            Assert.Equal(
                c.GetProperty("parameter_string").GetString(),
                PayFastSignature.ParameterString(fields, passphrase));

            Assert.Equal(c.GetProperty("signature").GetString(), PayFastSignature.Compute(fields, passphrase));
            Assert.True(PayFastSignature.Verify(fields, passphrase, c.GetProperty("signature").GetString()), id);

            executed++;
        }

        Assert.Equal(Declared("payment_request"), executed);
    }

    /// <summary>
    /// Field order is part of the signature. A <c>Dictionary</c> anywhere in this path would
    /// reorder silently and break every payment, so the corpus carries the same pairs twice
    /// in different orders and asserts they differ.
    /// </summary>
    [Fact]
    public void Reordering_the_same_fields_changes_the_signature()
    {
        var baseline = Find("payment_request", "req-order-baseline");
        var reordered = Find("payment_request", "req-order-matters");

        Assert.NotEqual(
            baseline.GetProperty("signature").GetString(),
            reordered.GetProperty("signature").GetString());

        Assert.Equal(
            baseline.GetProperty("signature").GetString(),
            PayFastSignature.Compute(FieldsOf(baseline), PassphraseOf(baseline)));

        Assert.Equal(
            reordered.GetProperty("signature").GetString(),
            PayFastSignature.Compute(FieldsOf(reordered), PassphraseOf(reordered)));
    }

    /// <summary>
    /// A merchant with no passphrase omits the pair entirely. Sending an empty
    /// <c>passphrase=</c> is a different string and does not verify.
    /// </summary>
    [Fact]
    public void An_absent_passphrase_omits_the_pair_rather_than_sending_it_empty()
    {
        var fields = new List<KeyValuePair<string, string?>> { new("merchant_id", "10000100") };

        Assert.Equal("merchant_id=10000100", PayFastSignature.ParameterString(fields, null));
        Assert.Equal("merchant_id=10000100", PayFastSignature.ParameterString(fields, ""));
        Assert.Equal("merchant_id=10000100&passphrase=x", PayFastSignature.ParameterString(fields, "x"));
    }

    /// <summary>Empty values are dropped — but "0" is not empty, and dropping it would change the signature.</summary>
    [Fact]
    public void Empty_values_are_dropped_and_zero_is_not_empty()
    {
        var fields = new List<KeyValuePair<string, string?>>
        {
            new("a", "1"),
            new("b", ""),
            new("c", null),
            new("d", "0"),
        };

        Assert.Equal("a=1&d=0", PayFastSignature.ParameterString(fields, null));
    }

    // ---- ITN ---------------------------------------------------------------

    [Fact]
    public void Itn_signatures_match_every_vector()
    {
        var executed = 0;

        foreach (var c in Corpus.GetProperty("itn").EnumerateArray())
        {
            var fields = FieldsOf(c);
            var passphrase = PassphraseOf(c);

            Assert.Equal(
                c.GetProperty("parameter_string").GetString(),
                PayFastSignature.ParameterString(fields, passphrase));

            Assert.Equal(c.GetProperty("signature").GetString(), PayFastSignature.Compute(fields, passphrase));
            executed++;
        }

        Assert.Equal(Declared("itn"), executed);
    }

    /// <summary>
    /// A valid signature says the message is authentic, not that the payment succeeded.
    /// Conflating the two credits a member for a failed payment — so the corpus carries a
    /// correctly-signed FAILED notification and this asserts it verifies.
    /// </summary>
    [Fact]
    public void A_failed_payment_still_carries_a_valid_signature()
    {
        var failed = Find("itn", "itn-failed");

        Assert.True(PayFastSignature.Verify(
            FieldsOf(failed), PassphraseOf(failed), failed.GetProperty("signature").GetString()));

        Assert.Contains(failed.GetProperty("fields").EnumerateArray(),
            f => f.GetProperty("key").GetString() == "payment_status"
                 && f.GetProperty("value").GetString() == "FAILED");
    }

    // ---- Verification --------------------------------------------------------

    [Fact]
    public void Verification_rejects_a_tampered_signature()
    {
        var c = Find("itn", "itn-complete");
        var fields = FieldsOf(c);
        var passphrase = PassphraseOf(c);
        var good = c.GetProperty("signature").GetString()!;

        Assert.True(PayFastSignature.Verify(fields, passphrase, good));
        Assert.True(PayFastSignature.Verify(fields, passphrase, good.ToUpperInvariant()));   // case-insensitive hex
        Assert.False(PayFastSignature.Verify(fields, passphrase, good[..^1] + "0"));
        Assert.False(PayFastSignature.Verify(fields, passphrase, good[..16]));
        Assert.False(PayFastSignature.Verify(fields, passphrase, ""));
        Assert.False(PayFastSignature.Verify(fields, passphrase, null));
        Assert.False(PayFastSignature.Verify(fields, "the-wrong-passphrase", good));
    }

    /// <summary>Changing any signed value invalidates it — the point of signing the amount.</summary>
    [Fact]
    public void Verification_rejects_a_tampered_amount()
    {
        var c = Find("itn", "itn-complete");
        var passphrase = PassphraseOf(c);
        var good = c.GetProperty("signature").GetString()!;

        var tampered = FieldsOf(c)
            .Select(f => f.Key == "amount_gross" ? new KeyValuePair<string, string?>(f.Key, "10000.00") : f)
            .ToList();

        Assert.False(PayFastSignature.Verify(tampered, passphrase, good));
    }

    [Fact]
    public void Every_corpus_section_is_declared_and_non_empty()
    {
        var sections = Corpus.EnumerateObject()
            .Where(p => p.Value.ValueKind == JsonValueKind.Array)
            .Select(p => p.Name).ToList();

        Assert.Equal(sections.Order(), Manifest.GetProperty("case_count").EnumerateObject().Select(p => p.Name).Order());
        Assert.All(sections, s => Assert.Equal(Corpus.GetProperty(s).GetArrayLength(), Declared(s)));
    }

    private static JsonElement Find(string section, string id) =>
        Corpus.GetProperty(section).EnumerateArray().First(c => c.GetProperty("id").GetString() == id);
}
